param([Parameter(Mandatory=$true)][string]$Image,[Parameter(Mandatory=$true)][string]$Domain,[string]$EnvironmentFile='.env.staging')
$ErrorActionPreference='Stop';$project=Split-Path -Parent $PSScriptRoot;$envPath=(Resolve-Path -LiteralPath (Join-Path $project $EnvironmentFile)).Path;if($Image -notmatch '@sha256:[a-fA-F0-9]{64}$'){throw 'Image must be pinned to an immutable sha256 digest.'};if($Domain -notmatch '^[a-z0-9.-]+$'){throw 'Invalid staging domain.'};$stateDir=Join-Path $project '.runtime';New-Item -ItemType Directory -Force -Path $stateDir|Out-Null;$currentFile=Join-Path $stateDir 'staging-current-image';$previousFile=Join-Path $stateDir 'staging-previous-image';if(Test-Path -LiteralPath $currentFile){Copy-Item -LiteralPath $currentFile -Destination $previousFile -Force};$env:WAREVANTA_IMAGE=$Image;$env:WAREVANTA_DOMAIN=$Domain;& docker compose --env-file $envPath -f (Join-Path $project 'compose.staging.yml') pull;if($LASTEXITCODE){throw 'Staging image pull failed'};& docker compose --env-file $envPath -f (Join-Path $project 'compose.staging.yml') up -d --remove-orphans;if($LASTEXITCODE){throw 'Staging deployment failed'};try{& (Join-Path $PSScriptRoot 'health-check.ps1') -Url "https://$Domain/api/ready";Set-Content -LiteralPath $currentFile -Value $Image;Write-Output "Staging deployment healthy: $Image"}catch{if(Test-Path -LiteralPath $previousFile){$env:WAREVANTA_IMAGE=(Get-Content -LiteralPath $previousFile -Raw).Trim();& docker compose --env-file $envPath -f (Join-Path $project 'compose.staging.yml') up -d --remove-orphans};throw 'Health verification failed; the previous image was restored when available.'}
